#pragma once

#include <string>
#include <optional>
#include "core/component_meta.h"
#include "core/stability.h"
#include "experiment/experiment_config.h"

namespace microbotica::experiment {

/// Loads experiment configuration from experiment.json.
///
/// MBCA-COMP-060
///
/// Reads the JSON representation of experiment.yaml (generated by
/// scripts/yaml_to_json.py). Validates schema_version, rejects
/// absolute paths, and builds ExperimentConfig.
class ExperimentLoader {
public:
    ExperimentLoader();

    static const core::ComponentMeta& interfaceMeta() {
        static const core::ComponentMeta meta{
            .component_id      = "MBCA-COMP-060",
            .component_version = "1.0.0",
            .stability         = core::StabilityLevel::Experimental,
            .description       = "Loads experiment configuration from experiment.json.",
            .preconditions     = {"experiment.json exists and is valid JSON",
                                  "schema_version major version is 1"},
            .postconditions    = {"ExperimentConfig is fully populated",
                                  "All paths are relative (no absolute paths)"},
            .invariants        = {"Loader does not modify any files"},
            .design_rationale  = "Uses JSON (not YAML) on the C++ side to avoid adding yaml-cpp "
                                 "as a dependency. The canonical source is experiment.yaml; "
                                 "experiment.json is a derived artifact.",
            .assumptions       = {"experiment.json was generated from experiment.yaml by "
                                  "scripts/yaml_to_json.py and is in sync"},
            .limitations       = {"Does not validate that referenced files (setup.py, world.usda) exist",
                                  "Does not parse or execute Python files"},
            .validated_regimes = {},
            .hazard_hints      = {
                "If experiment.json is stale (YAML edited but JSON not regenerated), "
                "the C++ side may load outdated configuration.",
            },
            .references        = {},
            .deprecation_notice = std::nullopt,
        };
        return meta;
    }

    /// Load an experiment from a directory.
    /// Reads <experiment_dir>/experiment.json.
    /// @param experiment_dir  Path to the experiment directory
    /// @return ExperimentConfig on success, std::nullopt on failure
    std::optional<ExperimentConfig> load(const std::string& experiment_dir) const;

    /// Load from an explicit JSON file path.
    std::optional<ExperimentConfig> loadFromJson(const std::string& json_path) const;

private:
    /// Validate that a path is relative (not absolute).
    bool isRelativePath(const std::string& path) const;

    /// Parse the JSON into ExperimentConfig.
    std::optional<ExperimentConfig> parseConfig(const nlohmann::json& j,
                                                 const std::string& source_path) const;
};

} // namespace microbotica::experiment
